"""Order checkout: prices an order, reserves stock, charges the customer and sends the receipt."""

import logging
from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

from shop.coupons import CouponBook
from shop.errors import OrderRejected, OutOfStock, PaymentDeclined
from shop.inventory import Inventory
from shop.models import Customer, Item, Order
from shop.payments import PaymentGateway, ReceiptNotifier
from shop.pricing import tax_rate

logger = logging.getLogger(__name__)

SHIPPING_CENTS = 490
FREE_SHIPPING_FROM_CENTS = 5000
VIP_DISCOUNT_PERCENT = 5


@dataclass(frozen=True)
class _Price:
    subtotal_cents: int
    discount_cents: int
    tax_cents: int
    shipping_cents: int

    @property
    def total_cents(self) -> int:
        return self.subtotal_cents - self.discount_cents + self.tax_cents + self.shipping_cents


def process_order(
    order: Order,
    customer: Customer,
    inventory: Inventory,
    gateway: PaymentGateway,
    notifier: ReceiptNotifier,
    coupons: CouponBook,
) -> str:
    """Checks out the order and returns the receipt id of the payment."""
    _validate_order(order)
    price = _price_order(order, customer, coupons)
    _reserve_stock(order, inventory)
    receipt_id = _charge_customer(order, customer, price.total_cents, inventory, gateway)
    _mark_paid(order, price.total_cents, inventory, coupons)
    _send_receipt(order, customer, receipt_id, notifier)
    return receipt_id


def _validate_order(order: Order) -> None:
    if not order.items:
        raise OrderRejected("order has no items")
    for item in order.items:
        if item.quantity <= 0:
            raise OrderRejected(f"invalid quantity for {item.sku}")


def _price_order(order: Order, customer: Customer, coupons: CouponBook) -> _Price:
    subtotal = _subtotal_cents(order.items)
    discount = _discount_cents(order, customer, subtotal, coupons)
    return _Price(
        subtotal_cents=subtotal,
        discount_cents=discount,
        tax_cents=_tax_cents(order.items, customer),
        shipping_cents=_shipping_cents(subtotal - discount),
    )


def _subtotal_cents(items: list[Item]) -> int:
    return sum(item.unit_price_cents * item.quantity for item in items)


def _tax_cents(items: list[Item], customer: Customer) -> int:
    # Tax is rounded per line, as the accounting export expects, and is charged on the undiscounted line price.
    rate = tax_rate(customer.country)
    return sum(
        int((Decimal(item.unit_price_cents * item.quantity) * rate).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        for item in items
    )


def _discount_cents(order: Order, customer: Customer, subtotal: int, coupons: CouponBook) -> int:
    discount = 0
    if order.coupon is not None:
        discount += _coupon_discount_cents(order.coupon, subtotal, coupons)
    if customer.vip:
        discount += _vip_discount_cents(subtotal - discount)
    return discount


def _coupon_discount_cents(code: str, subtotal: int, coupons: CouponBook) -> int:
    percent = coupons.discount_percent(code)
    if percent is None:
        raise OrderRejected(f"invalid coupon: {code}")
    return subtotal * percent // 100


def _vip_discount_cents(amount_cents: int) -> int:
    return amount_cents * VIP_DISCOUNT_PERCENT // 100


def _shipping_cents(amount_after_discount_cents: int) -> int:
    if amount_after_discount_cents >= FREE_SHIPPING_FROM_CENTS:
        return 0
    return SHIPPING_CENTS


def _reserve_stock(order: Order, inventory: Inventory) -> None:
    reserved: list[Item] = []
    try:
        for item in order.items:
            inventory.reserve(item.sku, item.quantity)
            reserved.append(item)
    except OutOfStock as error:
        _release_stock(reserved, inventory)
        order.status = "rejected"
        raise OrderRejected(f"out of stock: {error.sku}") from error


def _release_stock(items: list[Item], inventory: Inventory) -> None:
    for item in items:
        inventory.release(item.sku, item.quantity)


def _charge_customer(
    order: Order,
    customer: Customer,
    total_cents: int,
    inventory: Inventory,
    gateway: PaymentGateway,
) -> str:
    try:
        return gateway.charge(customer.email, total_cents)
    except PaymentDeclined as error:
        _release_stock(order.items, inventory)
        order.status = "payment_failed"
        raise OrderRejected(f"payment declined: {error}") from error


def _mark_paid(order: Order, total_cents: int, inventory: Inventory, coupons: CouponBook) -> None:
    for item in order.items:
        inventory.commit(item.sku, item.quantity)
    if order.coupon is not None:
        coupons.redeem(order.coupon)
    order.status = "paid"
    order.total_cents = total_cents
    logger.info("order %s paid: %s cents", order.id, total_cents)


def _send_receipt(order: Order, customer: Customer, receipt_id: str, notifier: ReceiptNotifier) -> None:
    try:
        notifier.send_receipt(customer.email, order.id, receipt_id)
    except Exception:
        logger.warning("receipt for order %s could not be sent", order.id, exc_info=True)


def refund_order(order: Order, customer: Customer, inventory: Inventory, gateway: PaymentGateway) -> None:
    """Refunds a paid order in full and puts its items back into stock."""
    if order.status != "paid":
        raise OrderRejected(f"order {order.id} is not paid")
    gateway.refund(customer.email, order.total_cents)
    for item in order.items:
        inventory.restock(item.sku, item.quantity)
    order.status = "refunded"
    logger.info("order %s refunded: %s cents", order.id, order.total_cents)

